import re


def _tokens(text):
    return set(re.findall(r"[A-Za-z]+|[\u4e00-\u9fff]{2,}", text.lower()))


def _chunk_key(chunk, index):
    return chunk.get("id", index)


def search_context(chunks, query, top_k=2, neighbor_window=1, max_context=6):
    # Split multi-part questions on Chinese/English question marks and
    # semicolons, keeping only substantive (non-empty) clauses.
    clauses = [c.strip() for c in re.split(r"[？?；;]", query) if c.strip()]
    if not clauses:
        clauses = [query.strip()] if query.strip() else []

    selected = {}

    # Reserve at least one relevant semantic anchor per substantive clause.
    for clause in clauses:
        terms = _tokens(clause)
        ranked = sorted(
            enumerate(chunks),
            key=lambda item: len(terms & _tokens(item[1].get("text", ""))),
            reverse=True,
        )
        for index, chunk in ranked[: max(top_k, 1)]:
            key = _chunk_key(chunk, index)
            if key not in selected:
                selected[key] = {**chunk, "retrieval_reason": "semantic"}

    # Add same-source neighboring pages within neighbor_window.
    anchors = list(selected.values())
    for anchor in anchors:
        source = anchor.get("source")
        page = anchor.get("page")
        if source is None or page is None:
            continue
        for index, chunk in enumerate(chunks):
            key = _chunk_key(chunk, index)
            if key in selected:
                continue
            if (
                chunk.get("source") == source
                and abs(chunk.get("page", 0) - page) <= neighbor_window
            ):
                selected[key] = {**chunk, "retrieval_reason": "neighbor"}

    return list(selected.values())[:max_context]
